  private static void pack25519(final byte[] o, final long[] n) {
    final long[] m = new long[16], t = new long[16];
    System.arraycopy(n, 0, t, 0, 16);
    car25519(t);
    car25519(t);
    car25519(t);
    for (int j = 0, b; j < 2; j++) {
      m[0] = t[0] - 0xffed;
      for (int i = 1; i < 15; i++) {
        m[i] = t[i] - 0xffff - ((m[i - 1] >> 16) & 1);
        m[i - 1] &= 0xffff;
      }
      m[15] = t[15] - 0x7fff - ((m[14] >> 16) & 1);
      b = (int) ((m[15] >> 16) & 1);
      m[14] &= 0xffff;
      sel25519(t, m, 1 - b);
    }
    for (int i = 0; i < 16; i++) {
      o[2 * i] = (byte) (t[i] & 0xff);
      o[2 * i + 1] = (byte) (t[i] >> 8);
    }
  }
